CREATE TABLE public.operator_access (user_id uuid PRIMARY KEY, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','removed')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.operator_access TO authenticated;
GRANT ALL ON public.operator_access TO service_role;
ALTER TABLE public.operator_access ENABLE ROW LEVEL SECURITY;
INSERT INTO public.operator_access(user_id,status) SELECT id,'approved' FROM public.profiles;
CREATE OR REPLACE FUNCTION public.is_approved(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.operator_access WHERE user_id=_uid AND status='approved') $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.can_manage(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_approved(_uid) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role::text IN ('admin','manager')) $$;
CREATE POLICY "own or approved team access status" ON public.operator_access FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.is_approved(auth.uid()));
CREATE OR REPLACE FUNCTION public.register_operator_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.operator_access(user_id) VALUES(new.id) ON CONFLICT DO NOTHING; RETURN new; END $$;
CREATE TRIGGER register_operator_access AFTER INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.register_operator_access();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'name',new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email); INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'operator'); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.set_operator_access(_user_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores'; END IF; IF _user_id=auth.uid() THEN RAISE EXCEPTION 'Não é possível remover seu próprio acesso'; END IF; IF _status NOT IN ('approved','removed') THEN RAISE EXCEPTION 'Status inválido'; END IF; UPDATE public.operator_access SET status=_status,updated_at=now() WHERE user_id=_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Operador não encontrado'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_operator_access(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_operator_access(uuid,text) TO authenticated;
CREATE POLICY "approved operators only" ON public.clients AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.client_users AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.client_devices AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.client_sensors AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.client_events AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.bypasses AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.shifts AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "approved operators only" ON public.custom_fields AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
CREATE POLICY "own profile or approved team" ON public.profiles AS RESTRICTIVE FOR ALL TO authenticated USING(id=auth.uid() OR public.is_approved(auth.uid())) WITH CHECK(id=auth.uid() OR public.is_approved(auth.uid()));
CREATE POLICY "own roles or approved team" ON public.user_roles AS RESTRICTIVE FOR ALL TO authenticated USING(user_id=auth.uid() OR public.is_approved(auth.uid())) WITH CHECK(public.is_approved(auth.uid()));
ALTER TABLE public.client_events ADD COLUMN archived_at timestamptz;
ALTER TABLE public.bypasses ADD COLUMN archived_at timestamptz;
COMMENT ON COLUMN public.client_events.archived_at IS 'Retention starts only after confirmed archive-file save. Legacy archived records remain protected with null timestamp.';
CREATE OR REPLACE FUNCTION public.guard_archive_state() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF new.archived OR new.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Use o arquivamento administrativo'; END IF; ELSE IF (new.archived IS DISTINCT FROM old.archived OR new.archived_at IS DISTINCT FROM old.archived_at) AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem arquivar'; END IF; IF (to_jsonb(new)-'archived'-'archived_at') IS DISTINCT FROM (to_jsonb(old)-'archived'-'archived_at') THEN new.archived=false; new.archived_at=null; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER guard_archive_state BEFORE INSERT OR UPDATE ON public.client_events FOR EACH ROW EXECUTE FUNCTION public.guard_archive_state();
CREATE TRIGGER guard_archive_state BEFORE INSERT OR UPDATE ON public.bypasses FOR EACH ROW EXECUTE FUNCTION public.guard_archive_state();
CREATE OR REPLACE FUNCTION public.archive_month(_month date,_archived boolean DEFAULT true) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; m integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores'; END IF; IF _archived THEN RAISE EXCEPTION 'Salve a cópia pelo botão Salvar e arquivar mês'; END IF; UPDATE public.client_events SET archived=false,archived_at=null WHERE event_date>=date_trunc('month',_month)::date AND event_date<(date_trunc('month',_month)+interval '1 month')::date; GET DIAGNOSTICS n=ROW_COUNT; UPDATE public.bypasses SET archived=false,archived_at=null WHERE end_date>=date_trunc('month',_month)::date AND end_date<(date_trunc('month',_month)+interval '1 month')::date; GET DIAGNOSTICS m=ROW_COUNT; RETURN n+m; END $$;
CREATE OR REPLACE FUNCTION public.prepare_archive_month(_month date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores'; END IF; RETURN jsonb_build_object('version',1,'month',date_trunc('month',_month)::date,'exported_at',now(),'events',coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM public.client_events e WHERE event_date>=date_trunc('month',_month)::date AND event_date<(date_trunc('month',_month)+interval '1 month')::date),'[]'::jsonb),'bypasses',coalesce((SELECT jsonb_agg(to_jsonb(b)) FROM public.bypasses b WHERE end_date>=date_trunc('month',_month)::date AND end_date<(date_trunc('month',_month)+interval '1 month')::date),'[]'::jsonb),'clients',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM public.clients c),'[]'::jsonb),'sensors',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.client_sensors s),'[]'::jsonb),'devices',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM public.client_devices d),'[]'::jsonb),'users',coalesce((SELECT jsonb_agg(to_jsonb(u)) FROM public.client_users u),'[]'::jsonb),'fields',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM public.custom_fields f),'[]'::jsonb),'operators',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.name)) FROM public.profiles p),'[]'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.confirm_saved_archive(_snapshot jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; m integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores'; END IF; UPDATE public.client_events e SET archived=true,archived_at=now() WHERE NOT e.archived AND EXISTS(SELECT 1 FROM jsonb_array_elements(_snapshot->'events') s WHERE s=to_jsonb(e)); GET DIAGNOSTICS n=ROW_COUNT; UPDATE public.bypasses b SET archived=true,archived_at=now() WHERE NOT b.archived AND b.end_date IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(_snapshot->'bypasses') s WHERE s=to_jsonb(b)); GET DIAGNOSTICS m=ROW_COUNT; RETURN n+m; END $$;
REVOKE ALL ON FUNCTION public.prepare_archive_month(date), public.confirm_saved_archive(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.prepare_archive_month(date), public.confirm_saved_archive(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.purge_expired_archives() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; m integer; BEGIN DELETE FROM public.client_events WHERE archived AND archived_at IS NOT NULL AND archived_at+interval '1 month'<=now(); GET DIAGNOSTICS n=ROW_COUNT; DELETE FROM public.bypasses WHERE archived AND end_date IS NOT NULL AND archived_at IS NOT NULL AND archived_at+interval '1 month'<=now(); GET DIAGNOSTICS m=ROW_COUNT; RETURN n+m; END $$;
REVOKE ALL ON FUNCTION public.purge_expired_archives() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_expired_archives() TO service_role;
CREATE INDEX client_events_archive_expiry ON public.client_events(archived_at) WHERE archived;
CREATE INDEX bypasses_archive_expiry ON public.bypasses(archived_at) WHERE archived;
CREATE EXTENSION IF NOT EXISTS pg_cron;